question.answer:
def carve(frame):
    return [frame[:4], frame[4:-2], frame[-2:], frame[::-1], frame[::2]]


def far_slice(frame):
    return frame[99:200]


def copy_of(frame):
    return frame[:]


def reverse_text(text):
    return text[::-1]

