question.answer:
def label_readings(readings):
    labels = []
    for i, reading in enumerate(readings):
        labels.append(f"{i}: {reading}")
    return labels


def positions_over(readings, limit):
    hits = []
    for i, reading in enumerate(readings):
        if reading > limit:
            hits.append(i)
    return hits


def total_power(readings):
    total = 0
    for reading in readings:
        total = total + reading
    return total

testcode.text:
readings = [12, 47, 9, 63, 47]
for line in label_readings(readings):
    print(line)
